def load_config(path="ratelimit.conf"):
    cfg = {}
    for line in open(path):
        line = line.strip()
        if not line or line.startswith("#"): continue
        k, v = line.split("=", 1)
        cfg[k.strip()] = int(v.strip())
    return cfg

